const nav = document.getElementById('ai4a11y-page-outline');
if (!nav) return false;
const links = [...nav.querySelectorAll('#ai4a11y-page-outline-list a')];
const names = links.map(a => a.textContent.replace(/\s+/g, ' ').trim());
const want = ['Community Support Grant Guide', 'Eligibility Criteria', 'Required Documentation',
  'Proof of Identity', 'Proof of Address and Income', 'How to Apply', 'Appeals and Reviews'];
if (JSON.stringify(names) !== JSON.stringify(want)) return false;
// Each link leads to an element on the page with that heading's text.
return links.every((a, i) => {
  const id = (a.getAttribute('href') || '').replace(/^#/, '');
  const target = id && document.getElementById(id);
  return !!target && target.textContent.replace(/\s+/g, ' ').trim() === want[i];
});

